def isi_total_harga(apps, schema_editor):
    """Booking lama diberi total harga dari harga akhir paketnya."""
    Booking = apps.get_model('app', 'Booking')
    for b in Booking.objects.select_related('package'):
        p = b.package
        harga = p.harga_potongan if p.harga_potongan and 0 < p.harga_potongan < p.price else p.price
        b.total_harga = harga
        b.save(update_fields=['total_harga'])

    # Booking lama yang masih berjalan dan belum lunas: buatkan tagihan pelunasan (jatuh tempo H-1 sesi)
    Payment = apps.get_model('app', 'Payment')
    hari_ini = datetime.date.today()
    # Booking yang sudah dibatalkan: tagihan yang belum dibayar ikut dibatalkan
    for b in Booking.objects.filter(status='cancelled'):
        Payment.objects.filter(booking=b, status__in=['pending', 'failed', 'expired']).update(status='cancelled')

    for b in Booking.objects.exclude(status__in=['cancelled', 'completed']):
        ps = list(Payment.objects.filter(booking=b))
        if any(p.jenis == 'pelunasan' for p in ps):
            continue
        tercatat = sum(p.amount for p in ps if p.status in ('pending', 'paid', 'partial'))
        sisa = b.total_harga - tercatat
        if sisa > 0 and b.booking_date >= hari_ini:
            Payment.objects.create(booking=b, amount=sisa, payment_method='midtrans', jenis='pelunasan',
                                   due_date=b.booking_date - datetime.timedelta(days=1), status='pending')


